function recoveryDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('WC3AssetStudioRecovery',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('recovery'))req.result.createObjectStore('recovery',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
