async function searchAssets(){const q=$('#proAssetQuery')?.value||'',type=$('#proAssetType')?.value||'all';if(!window.WC3_CASC?.searchAssets){status('This build does not expose CASC asset search.');return;}const requestId=++pro.assetSearchSeq,btn=$('#proAssetSearch');if(btn){btn.disabled=true;btn.textContent='Searching CASC…';}try{const r=await window.WC3_CASC.searchAssets(q,type,250);if(requestId!==pro.assetSearchSeq)return;pro.assetResults=r.results||[];pro.assetSelected=pro.assetResults[0]||'';stopAssetPreviewAnimation();pro.assetPreviewModel=null;pro.assetPreviewRuntime=null;pro.assetPreviewImage=null;pro.assetPreviewPath='';renderAssetResults();status(`Warcraft Library: ${pro.assetResults.length} result(s)`);}catch(e){if(requestId===pro.assetSearchSeq)status(`Warcraft Library search failed: ${e.message||e}`);}finally{if(btn&&requestId===pro.assetSearchSeq){btn.disabled=false;btn.textContent='Search CASC';}}}
