function applyCamera(){const m=model(),c=m?.cameras?.[iv($('#proCamera').value,-1)];if(!m||!c)return;historyModel('Edit camera');c.name=String($('#proCameraName').value||c.name||'Camera').slice(0,79);c.position=getVals('proCamPos',3);c.targetPosition=getVals('proCamTarget',3);c.fieldOfView=Math.max(.01,n($('#proCamFov').value,.7));c.nearClippingPlane=Math.max(.01,n($('#proCamNear').value,8));c.farClippingPlane=Math.max(c.nearClippingPlane+1,n($('#proCamFar').value,5000));m.__cameraEdited=true;dirty();}
function fxTimingMode(x){if(x?.__editorTiming?.mode)return x.__editorTiming.mode;if(x?.tracks?.KP2V?.keys?.length)return'selected';return'infinite';}
function renderFxEditor(){const m=model(),s=$('#proFx');if(!s)return;const fx=m?.particleEmitters2||[];const prev=s.value;s.innerHTML=fx.map((x,i)=>`<option value="${i}">${i+1}. ${esc(x.name||'ParticleEmitter2')}</option>`).join('');if([...s.options].some(o=>o.value===prev))s.value=prev;const x=fx[iv(s.value,0)];if(!x)return;$('#proFxRate').value=n(x.emissionRate,0);$('#proFxLife').value=n(x.lifeSpan,1);$('#proFxSpeed').value=n(x.speed,0);$('#proFxGravity').value=n(x.gravity,0);$('#proFxVariation').value=n(x.variation,0);$('#proFxLatitude').value=n(x.latitude,0);$('#proFxWidth').value=n(x.width,1);$('#proFxLength').value=n(x.length,1);$('#proFxTexture').value=iv(x.textureId,0);$('#proFxRows').value=`${Math.max(1,iv(x.rows,1))} x ${Math.max(1,iv(x.columns,1))}`;$('#proFxFilter').value=String(iv(x.filterMode,0));$('#proFxHeadTail').value=String(iv(x.headOrTail,0));$('#proFxTail').value=n(x.tailLength,0);$('#proFxTimeMiddle').value=n(x.timeMiddle,.5);$('#proFxPriority').value=iv(x.priorityPlane,0);$('#proFxReplaceable').value=iv(x.replaceableId,0);$('#proFxSquirt').checked=!!x.squirt;const seqSel=$('#proFxSequences'),selected=new Set((x.__editorTiming?.sequenceIds||[]).map(Number));if(seqSel){seqSel.innerHTML=(m.sequences||[]).map((q,i)=>`<option value="${i}"${selected.has(i)?' selected':''}>${i+1}. ${esc(q.name||`Sequence ${i+1}`)} · ${q.start}–${q.end}</option>`).join('');}const mode=fxTimingMode(x);$('#proFxTiming').value=mode;const cs=x.__editorTiming||{};$('#proFxStart').value=Number.isFinite(+cs.start)?+cs.start:(I.currentSequence?.()?.start||0);$('#proFxEnd').value=Number.isFinite(+cs.end)?+cs.end:(I.currentSequence?.()?.end||0);updateFxTimingUi();}
function updateFxTimingUi(){const mode=$('#proFxTiming')?.value||'infinite',seq=$('#proFxSequences'),start=$('#proFxStart'),end=$('#proFxEnd'),info=$('#proFxTimingInfo');if(seq)seq.disabled=mode!=='selected';if(start)start.disabled=mode!=='custom';if(end)end.disabled=mode!=='custom';const cur=I.currentSequence?.();if(info)info.textContent=mode==='infinite'?'Infinite: no KP2V track; emitter can run in every animation.':mode==='current'?`Current animation only: ${cur?.name||'no sequence selected'}.`:mode==='selected'?'Selected animations: KP2V is 1 only inside the selected sequence ranges.':'Custom range: KP2V is 1 only between Start and End frames.';}
function applyFx(){const m=model(),index=iv($('#proFx').value,-1),x=m?.particleEmitters2?.[index];if(!m||!x)return;historyModel('Edit particle emitter');x.emissionRate=n($('#proFxRate').value,0);x.lifeSpan=Math.max(.01,n($('#proFxLife').value,1));x.speed=n($('#proFxSpeed').value,0);x.gravity=n($('#proFxGravity').value,0);x.variation=Math.max(0,n($('#proFxVariation').value,0));x.latitude=n($('#proFxLatitude').value,0);x.width=Math.max(0,n($('#proFxWidth').value,1));x.length=Math.max(0,n($('#proFxLength').value,1));x.textureId=Math.max(0,iv($('#proFxTexture').value,0));const mm=String($('#proFxRows').value||'1x1').match(/(\d+)\D+(\d+)/);if(mm){x.rows=Math.max(1,+mm[1]);x.columns=Math.max(1,+mm[2]);}x.filterMode=Math.max(0,iv($('#proFxFilter').value,0));x.filterModeName=['Blend','Additive','Modulate','Modulate2x','AlphaKey'][x.filterMode]||`Filter ${x.filterMode}`;x.headOrTail=Math.max(0,Math.min(2,iv($('#proFxHeadTail').value,0)));x.tailLength=Math.max(0,n($('#proFxTail').value,0));x.timeMiddle=clamp(n($('#proFxTimeMiddle').value,.5),0,1);x.priorityPlane=iv($('#proFxPriority').value,0);x.replaceableId=Math.max(0,iv($('#proFxReplaceable').value,0));x.squirt=$('#proFxSquirt')?.checked?1:0;const mode=$('#proFxTiming')?.value||'infinite',sequenceIds=[...($('#proFxSequences')?.selectedOptions||[])].map(o=>iv(o.value,-1)).filter(i=>i>=0);API.setParticleEmitterTiming?.(index,{mode,sequenceIds,start:n($('#proFxStart')?.value,0),end:n($('#proFxEnd')?.value,0)});m.__effectsEdited=true;dirty();renderFxEditor();}

function geoOp(op){const m=model(),idx=state.selectedGeosetIndex,g=m?.geosets?.[idx];if(!g)return;if(/^mirror/.test(op)&&String(m.type||'').toUpperCase()!=='MDX'){status('Mirror is currently save-safe for MDX only. Convert/open the binary MDX before mirroring.');return;}const snap=I.captureGeosetSnapshot?.(idx,`Geometry: ${op}`);if(snap)I.pushModelHistorySnapshot?.(snap);const verts=g.vertices||[],norm=g.normals||[];if(/^mirror/.test(op)){const axis={mirrorX:'x',mirrorY:'y',mirrorZ:'z'}[op];for(const v of verts)v[axis]=-n(v[axis]);for(const q of norm)q[axis]=-n(q[axis]);const faces=g.faces||g.triangles||[];for(let fi=0;fi<faces.length;fi++){const t=faces[fi];if(Array.isArray(t)&&t.length>=3){const z=t[1];t[1]=t[2];t[2]=z;}else if(t&&Number.isFinite(t.b)&&Number.isFinite(t.c)){const z=t.b;t.b=t.c;t.c=z;}}g.__topologyEdited=true;}else if(op==='flipNormals'){for(const q of norm){q.x=-n(q.x);q.y=-n(q.y);q.z=-n(q.z);}}else if(op==='recalcNormals'){recalcNormals(g);}else if(op==='center'){if(verts.length){const c={x:verts.reduce((a,v)=>a+n(v.x),0)/verts.length,y:verts.reduce((a,v)=>a+n(v.y),0)/verts.length,z:verts.reduce((a,v)=>a+n(v.z),0)/verts.length};for(const v of verts){v.x-=c.x;v.y-=c.y;v.z-=c.z;}}}g.__geometryEdited=true;m.__geometryEdited=true;I.invalidateGeometryCache?.();I.invalidatePickCache?.();dirty();}
function recalcNormals(g){const verts=g.vertices||[],tris=g.triangles||g.faces||[],acc=verts.map(()=>[0,0,0]);for(const t of tris){const ids=Array.isArray(t)?t:[t.a,t.b,t.c];if(ids.length<3)continue;const a=verts[ids[0]],b=verts[ids[1]],c=verts[ids[2]];if(!a||!b||!c)continue;const ux=b.x-a.x,uy=b.y-a.y,uz=b.z-a.z,vx=c.x-a.x,vy=c.y-a.y,vz=c.z-a.z,nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx;for(const id of ids.slice(0,3)){acc[id][0]+=nx;acc[id][1]+=ny;acc[id][2]+=nz;}}g.normals=acc.map(([x,y,z])=>{const l=Math.hypot(x,y,z)||1;return{x:x/l,y:y/l,z:z/l};});}

