function shortcutHandler(e){if(document.body.dataset.module!=='model'||e.ctrlKey||e.metaKey)return;const t=e.target;if(t&&(/INPUT|TEXTAREA|SELECT/.test(t.tagName)||t.isContentEditable))return;const k=e.key.toLowerCase();if(k==='g'){state.activePropPanel='geosets';const b=$('[data-model-geoset-tool="move"]');b?.click();e.preventDefault();}else if(k==='r'){const b=$('[data-model-geoset-tool="rotate"]');b?.click();e.preventDefault();}else if(k==='s'){const b=$('[data-model-geoset-tool="scale"]');b?.click();e.preventDefault();}else if(k==='f'){if(state.selectedNodeId>=0)I.focusNodeInViewport?.(state.selectedNodeId,{fit:true});else if(state.selectedGeosetIndex>=0)$('#modelGeosetFocusBtn')?.click();e.preventDefault();}else if(k==='h'&&!e.altKey){$('#modelGeosetHideBtn')?.click();e.preventDefault();}else if(k==='h'&&e.altKey){$('#modelGeosetShowAllBtn')?.click();e.preventDefault();}else if(e.shiftKey&&k==='d'){$('#modelGeosetCloneBtn')?.click();e.preventDefault();}}


